VALUES ('schulausflug-a1', $chunk${"t":"Der Schulausflug – A1","d":"Der Lernende kann Datum, Treffpunkt, Uhrzeit, benötigte Sachen und einfache Regeln für einen Schulausflug verstehen und nachfragen.","s":[["Unsere Klasse macht einen Schulausflug.","Thema verstehen"],["Der Ausflug ist am Freitag.","Datum/Tag verstehen"],["Wir treffen uns vor der Schule.","Treffpunkt verstehen"],["Bitte seid um acht Uhr da.","Uhrzeit verstehen"],["Wir fahren mit dem Bus.","Verkehrsmittel verstehen"],["Wir fahren ins Museum.","Ziel verstehen"],["Bitte nehmt eine Jause mit.","Mitbringen verstehen"],["Nehmt bitte Wasser mit.","wichtige Sache"],["Zieht feste Schuhe an.","Anweisung verstehen"],["Die Eltern unterschreiben den Zettel.","Unterschrift verstehen"],["Der Ausflug kostet fünf Euro.","Preis verstehen"],["Der Bus fährt um 8:15 Uhr ab.","Abfahrtszeit"],["Wir sind um 15 Uhr zurück.","Rückkehr"],["Die Eltern holen die Kinder vor der Schule ab.","Abholort"],["Was muss mein Kind mitbringen?","wichtige Rückfrage"]],"v":[["der Schulausflug","die Schulausflüge","gemeinsamer Ausflug der Klasse","Der Schulausflug ist am Freitag."],["der Zettel","die Zettel","Informationsblatt","Bitte lesen Sie den Zettel."],["das Datum","die Daten","Tag des Ausflugs","Auf dem Zettel steht das Datum."],["der Treffpunkt","die Treffpunkte","Ort zum Treffen","Der Treffpunkt ist vor der Schule."],["die Uhrzeit","die Uhrzeiten","Zeitangabe","Welche Uhrzeit steht auf dem Zettel?"],["der Bus","die Busse","Verkehrsmittel","Wir fahren mit dem Bus."],["das Museum","die Museen","Ausflugsziel","Wir besuchen ein Museum."],["die Jause","die Jausen","Essen für unterwegs","Mein Kind nimmt eine Jause mit."],["das Wasser","—","Getränk","Bitte Wasser mitnehmen."],["die Schuhe","—","Fußbekleidung","Bitte feste Schuhe anziehen."],["die Jacke","die Jacken","Oberbekleidung","Nehmen Sie eine Jacke mit."],["die Erlaubnis","die Erlaubnisse","Zustimmung","Die Eltern geben die Erlaubnis."],["die Unterschrift","die Unterschriften","Signatur","Die Unterschrift fehlt."],["die Kosten","—","Preis/Ausgaben","Die Kosten sind fünf Euro."],["mitbringen","—","mitnehmen und bringen","Was muss mein Kind mitbringen?"],["mitnehmen","—","bei sich haben","Bitte Wasser mitnehmen."],["unterschreiben","—","Name als Signatur schreiben","Bitte hier unterschreiben."],["abfahren","—","starten","Der Bus fährt um acht Uhr ab."],["zurückkommen","—","wieder ankommen","Wir kommen um 15 Uhr zurück."],["abholen","—","jemanden holen","Ich hole mein Kind ab."],["treffen","—","zusammenkommen","Wir treffen uns vor der Schule."],["kosten","—","einen Preis haben","Der Ausflug kostet fünf Euro."],["am Freitag","—","Zeitangabe","Der Ausflug ist am Freitag."],["um acht Uhr","—","Uhrzeit","Wir treffen uns um acht Uhr."],["vor der Schule","—","Ort","Treffpunkt ist vor der Schule."]],"p":["1. Wo ist der Treffpunkt? Der Treffpunkt ist vor der Schule.","2. Wo wartet der Bus? Der Bus wartet vor dem Eingang.","3. Wo sind die Kinder? Die Kinder stehen neben dem Bus.","4. Wo liegt der Zettel? Der Zettel liegt auf dem Tisch.","5. Wo ist die Jause? Die Jause ist im Rucksack.","6. Wo treffen die Eltern die Kinder? Die Eltern warten vor der Schule."],"dgs":[[1,"Mutter","Wann ist der Schulausflug?","Eltern fragen nach"],[1,"Lehrerin","Am Freitag.","Eltern fragen nach"],[1,"Mutter","Um wie viel Uhr treffen sich die Kinder?","Eltern fragen nach"],[1,"Lehrerin","Um acht Uhr vor der Schule.","Eltern fragen nach"],[1,"Mutter","Was muss mein Kind mitbringen?","Eltern fragen nach"],[1,"Lehrerin","Eine Jause, Wasser und feste Schuhe.","Eltern fragen nach"],[2,"Vater","Muss ich den Zettel unterschreiben?","Erlaubnis und Kosten"],[2,"Lehrerin","Ja, bitte.","Erlaubnis und Kosten"],[2,"Vater","Wie viel kostet der Ausflug?","Erlaubnis und Kosten"],[2,"Lehrerin","Fünf Euro.","Erlaubnis und Kosten"],[2,"Vater","Wann sind die Kinder zurück?","Erlaubnis und Kosten"],[2,"Lehrerin","Um ungefähr 15 Uhr.","Erlaubnis und Kosten"]],"gn":[["W-Fragen: wann/wo/was/wie viel","W-Fragen beginnen mit einem Fragewort. Danach folgt in der Regel das Verb.","Was brauchen wir? · Wo ist der Raum? · Wann beginnt es?"],["Modalverb müssen","Modalverben wie können, müssen, sollen und dürfen stehen konjugiert; der zweite Infinitiv steht am Satzende.","Was muss ich mitbringen? · Können Sie mir helfen? · Was soll mein Kind machen?"],["Trennbare Verben mitbringen/abholen","Trennbare Verben teilen sich im Hauptsatz: abholen → Ich hole mein Kind ab.","Bitte nehmt eine Jause mit. · Nehmt bitte Wasser mit. · Zieht feste Schuhe an."],["Imperativ mit Sie","Bei höflichen Aufforderungen mit Sie steht das Verb vorne: „Bitte unterschreiben Sie hier.“","Bitte unterschreiben Sie hier. · Öffnen Sie das Buch. · Nehmen Sie den Zettel mit."],["Zeitangaben am/um","Für Uhrzeiten nutzt man meist „um“, für Wochentage/Datum „am“. „bis“ markiert eine Frist.","Der Ausflug ist am Freitag. · Bitte seid um acht Uhr da. · Der Bus fährt um 8:15 Uhr ab. · Wir sind um 15 Uhr zurück."],["Akkusativ","Nach Verben wie brauchen, nehmen, haben oder machen steht das direkte Objekt häufig im Akkusativ.","Ich brauche einen Schulausflug. · Ich brauche eine Information. · Ich nehme das Formular."],["Ortsangaben vor/in/neben","Ortsangaben helfen bei der Orientierung. Typisch sind in, auf, an, neben, vor, hinter und gegenüber.","Der Treffpunkt ist vor der Schule. · Der Bus wartet vor dem Eingang. · Die Kinder stehen neben dem Bus. · Der Zettel liegt auf dem Tisch."]],"q":[["practice","Wer beginnt das Gespräch?","Mutter","Lehrerin","Niemand"],["practice","Welche Aussage kommt im Dialog wirklich vor?","Um wie viel Uhr treffen sich die Kinder?","Wie viel kostet der Ausflug?","Ich bestelle eine Pizza."],["practice","Welche Aussage gehört zu diesem Dialog?","Wie viel kostet der Ausflug?","Um wie viel Uhr treffen sich die Kinder?","Der Zug fährt um sieben Uhr."],["practice","Welche Antwort folgt logisch?","Fünf Euro.","Wann ist der Schulausflug?","Ich möchte eine Jacke kaufen."],["grammar","Welches Fragewort fragt nach einem Ort?","Wo","Wann","Was"],["grammar","Welches Fragewort fragt nach einer Zeit?","Wann","Wo","Wer"],["grammar","Welches Fragewort fragt nach einer Sache/Information?","Was","Wo","Wie alt"],["grammar","Welche Frage passt am besten zum Thema?","Was brauchen wir?","Wie teuer ist ein Auto?","Wo ist das Schwimmbad?"],["grammar","Welche zweite Frage passt ebenfalls?","Wo ist der Raum?","Welche Farbe hat das Wetter?","Wie groß ist die Bank?"],["grammar","Bei einem Modalverb steht der zweite Infinitiv ...","am Satzende","immer am Anfang","direkt vor dem Subjekt"],["grammar","Welche Form ist richtig?","Was muss ich mitbringen?","Muss ich mitbringen was?","Ich muss was mitbringen muss."],["grammar","Welche Form ist höflich?","Können Sie mir helfen?","Hilf!","Du helfen."],["grammar","Welche Frage passt zum Thema?","Was soll mein Kind machen?","Kann die Farbe rechnen?","Muss der Bus ein Heft sein?"],["grammar","Bei trennbaren Verben steht der abgetrennte Teil ...","oft am Satzende","immer direkt nach dem Subjekt","nie im Satz"],["grammar","Welche Form ist korrekt?","Bitte nehmt eine Jause mit.","Ich abhole mein Kind.","Ich mein Kind abholen."],["grammar","Welche Form ist korrekt?","Nehmt bitte Wasser mit.","Ich ausfülle das Formular.","Ich Formular fülle."],["grammar","Welche Aussage enthält ein trennbares Verb?","Bitte nehmt eine Jause mit.","Die Schule ist groß.","Deutsch ist gut."],["grammar","Welche Form ist eine höfliche Anweisung?","Bitte unterschreiben Sie hier.","Du sofort!","Kein Verb."],["grammar","Welche Form passt zur Sie-Anrede?","Öffnen Sie das Buch.","Öffnest du Buch.","Buch öffnen du."],["grammar","Was macht „bitte“?","Es macht die Aufforderung höflicher.","Es verneint den Satz.","Es nennt eine Uhrzeit."],["grammar","Welche Anweisung ist vollständig?","Nehmen Sie den Zettel mit.","Nur ein Nomen.","Ohne Verb."],["grammar","Welche Präposition passt zu einer Uhrzeit?","um","am","im"],["grammar","Welche Präposition passt zu einem Wochentag?","